function action(text) {
  var notebook = String((openclip.options && openclip.options.notebook) || '').trim();
  var url = 'upnote://x-callback-url/note/new?text=' + encodeURIComponent(text);
  if (notebook) url += '&notebook=' + encodeURIComponent(notebook);
  openclip.openURL(url);
}
